def tensor():
    def kronecker_product(*arrays):
        if not arrays:
            return np.identity(1)
        array, rest = arrays[0], tuple(arrays[1:])
        shape = (array.shape[0],) + tuple(a.shape for a in rest)
        prod = np.block([[a[i, j]*b for j in range(b.shape[1])] for i, a in enumerate(array) for b in rest])
        return prod.reshape(shape)

    M = kronecker_product(*args)
    return M
```

