def ichol(A):
    N = len(A)
    L = np.zeros((N, N))
    for i in range(1, N):
        L[i, i] = ((A[i, i] - sum(L[j, i]**2 for j in range(i))) ** 0.5)
    for i in reversed(range(1, N)):
        for j in range(i+1, N):
            L[j, i] = (A[j, i] - sum(L[j, k]*L[i, k] for k in range(1, i))) / L[i, i]
    return L
```

